<?php
namespace Nakhostin\PerformanceEngine\CSS;
final class StylesheetStrategyApplier { private $deferred = array(); private $registered = false; public function apply( array $decisions, bool $safe_mode = true ): array { $policy = new CSSOptimizationPolicy(); $applied = array(); foreach ( $decisions as $handle => $evidence ) { $handle = sanitize_key( (string) $handle ); $decision = $policy->decide( (array) $evidence, $safe_mode ); if ( CSSOptimizationPolicy::UNLOAD === $decision ) { wp_dequeue_style( $handle ); $applied[ $handle ] = $decision; } elseif ( CSSOptimizationPolicy::DEFER === $decision ) { $this->deferred[ $handle ] = true; $applied[ $handle ] = $decision; } } if ( $this->deferred && ! $this->registered ) { $this->registered = true; add_filter( 'style_loader_tag', array( $this, 'filter_tag' ), 20, 4 ); } return $applied; } public function filter_tag( string $html, string $handle ): string { if ( empty( $this->deferred[ $handle ] ) || false !== stripos( $html, ' media=' ) || false !== stripos( $html, ' onload=' ) ) { return $html; } $deferred = preg_replace( '/<link\s/i', '<link media="print" onload="this.media=\'all\'" ', $html, 1 ); return is_string( $deferred ) ? $deferred . '<noscript>' . $html . '</noscript>' : $html; } }
